import random
import struct
from typing import List

# This generator targets raw byte buffers consumed by CRC functions and classes.
# Fuzzer stubs use FUZZ_PARAM_STR() to obtain a std::string whose bytes are
# interpreted directly as uint8_t buffers. Our goal is to generate valid, interesting
# byte sequences that exercise different CRC behaviors (patterns, lengths, alignment,
# and content diversity) while remaining within 4096 bytes.

# Strategy
# - Produce buffers with diverse lengths: 0, 1, small, powers of two, just-below/above boundaries,
#   and random lengths up to 1024 (stubs cap processing to 1024 anyway).
# - Mix content patterns: all-zero, all-0xFF, incremental counters, repeating small patterns,
#   alternating bits, random blocks, high-entropy and low-entropy regions, and embedded short
#   ASCII segments.
# - Randomly interleave segments to form the final buffer to increase variability.
# - Keep total size <= 2048 (well under the 4096 limit) since stubs slice to <=1024 per call.

_MAX_TOTAL = 2048


def _rand_len(r: random.Random) -> int:
    # Favor interesting sizes including boundaries used in stubs
    choices = [
        0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 768, 1000, 1023, 1024
    ]
    if r.random() < 0.6:
        return r.choice(choices)
    # otherwise pick a random in [0, 1200]
    return r.randint(0, 1200)


def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n


def _pattern_ff(n: int) -> bytes:
    return b"\xFF" * n


def _pattern_inc(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))


def _pattern_alt(n: int, a: int = 0x55, b: int = 0xAA) -> bytes:
    return bytes((a if (i & 1) == 0 else b) for i in range(n))


def _pattern_repeat(r: random.Random, n: int) -> bytes:
    # Repeat a short motif (length 1..8)
    if n <= 0:
        return b""
    mlen = r.randint(1, 8)
    motif = bytes(r.getrandbits(8) for _ in range(mlen))
    return (motif * (n // mlen)) + motif[: n % mlen]


def _pattern_random(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _pattern_ascii(r: random.Random, n: int) -> bytes:
    # Embed common ASCII tokens helpful for table-driven paths or simple text-like data
    tokens = [
        b"hello", b"world", b"CRC", b"checksum", b"data", b"Arduino", b"123456789", b"\n",
        b"\r\n", b"END", b"BEGIN", b"--", b"==", b"::", b"param"
    ]
    out = bytearray()
    while len(out) < n:
        t = r.choice(tokens)
        # Occasionally insert a random byte run to mix entropy
        if r.random() < 0.4:
            run = _pattern_random(r, r.randint(1, 12))
            out.extend(run)
        out.extend(t)
    return bytes(out[:n])


def _pattern_edges(r: random.Random) -> bytes:
    # Construct a small block containing values near edges (0x00, 0x01, 0xFE, 0xFF) and transitions
    vals = [0x00, 0x01, 0x7F, 0x80, 0xFE, 0xFF]
    block = bytearray()
    for v in vals:
        block.extend(bytes([v]) * r.randint(1, 6))
    # Add transitions 00->FF and FF->00 sequences
    block.extend(b"\x00\xFF" * r.randint(2, 6))
    block.extend(b"\xFF\x00" * r.randint(2, 6))
    return bytes(block)


def _make_segment(r: random.Random) -> bytes:
    # Choose a pattern type and length
    n = _rand_len(r)
    kind = r.choice([
        "zero", "ff", "inc", "alt", "repeat", "random", "ascii", "edges"
    ])
    if kind == "zero":
        return _pattern_zero(n)
    if kind == "ff":
        return _pattern_ff(n)
    if kind == "inc":
        return _pattern_inc(n, start=r.randint(0, 255))
    if kind == "alt":
        a = r.choice([0x55, 0xAA, 0x00, 0xFF, 0x33, 0xCC])
        b = r.choice([x for x in [0x55, 0xAA, 0x00, 0xFF, 0x33, 0xCC] if x != a])
        return _pattern_alt(n, a, b)
    if kind == "repeat":
        return _pattern_repeat(r, n)
    if kind == "random":
        return _pattern_random(r, n)
    if kind == "ascii":
        return _pattern_ascii(r, n)
    if kind == "edges":
        base = _pattern_edges(r)
        # Tile or slice to desired n
        if n <= 0:
            return b""
        tiled = (base * (n // len(base) + 1))[:n]
        return tiled
    return b""


def _mix_segments(r: random.Random) -> bytes:
    # Build between 1 and 8 segments, interleave different patterns.
    total = 0
    segs: List[bytes] = []
    count = r.randint(1, 8)
    for _ in range(count):
        seg = _make_segment(r)
        if not seg:
            # Include empty segment sometimes to cover zero-length cases
            if r.random() < 0.3:
                segs.append(b"")
            continue
        # Occasionally trim segment to target size cap
        if total + len(seg) > _MAX_TOTAL:
            seg = seg[: max(0, _MAX_TOTAL - total)]
        segs.append(seg)
        total += len(seg)
        if total >= _MAX_TOTAL:
            break
    # Occasionally shuffle or reverse some segments to vary boundaries
    if r.random() < 0.3:
        r.shuffle(segs)
    if r.random() < 0.2 and segs:
        i = r.randrange(len(segs))
        segs[i] = segs[i][::-1]
    return b"".join(segs)[:_MAX_TOTAL]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # With some probability, generate a single focused pattern; otherwise mix segments
    if r.random() < 0.35:
        buf = _make_segment(r)
    else:
        buf = _mix_segments(r)

    # Ensure length variety: occasionally force exact interesting sizes by padding or slicing
    target_lengths = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1000, 1023, 1024]
    if r.random() < 0.25:
        tlen = r.choice(target_lengths)
        if tlen <= len(buf):
            buf = buf[:tlen]
        else:
            # pad with a simple deterministic extension to avoid invalid/malformed content
            pad_kind = r.choice(["zero", "ff", "inc"])
            need = tlen - len(buf)
            if pad_kind == "zero":
                buf += _pattern_zero(need)
            elif pad_kind == "ff":
                buf += _pattern_ff(need)
            else:
                start = buf[-1] if buf else r.randint(0, 255)
                buf += _pattern_inc(need, (start + 1) & 0xFF)

    # Final guard: cap to 2048 bytes (<=4096 requirement; stubs further cap to 1024)
    return buf[:_MAX_TOTAL]
